async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  const decoder = new TextDecoder("utf-8");

  let accepted = 0;
  let rejected = 0;
  let lineNumber = 0;
  let pending = "";
  let completedNormally = false;

  async function processLine(source, terminatedByLf) {
    const line = terminatedByLf && source.endsWith("\r")
      ? source.slice(0, -1)
      : source;

    const lineNumberForVisitor = ++lineNumber;

    if (line.trim() === "") {
      return false;
    }

    let value;
    try {
      value = JSON.parse(line);
    } catch {
      rejected++;
      return false;
    }

    accepted++;

    if (await visitor({ line: lineNumberForVisitor, value }) === false) {
      return true;
    }

    return false;
  }

  async function processText(text) {
    let start = 0;

    while (true) {
      const end = text.indexOf("\n", start);

      if (end === -1) {
        pending += text.slice(start);
        return false;
      }

      let line;
      if (pending.length === 0) {
        line = text.slice(start, end);
      } else {
        pending += text.slice(start, end);
        line = pending;
        pending = "";
      }

      if (await processLine(line, true)) {
        return true;
      }

      start = end + 1;
    }
  }

  try {
    while (true) {
      const result = await reader.read();

      if (result.done) {
        break;
      }

      if (await processText(decoder.decode(result.value, { stream: true }))) {
        return { accepted, rejected, stopped: true };
      }
    }

    if (await processText(decoder.decode())) {
      return { accepted, rejected, stopped: true };
    }

    if (pending.length > 0 && await processLine(pending, false)) {
      return { accepted, rejected, stopped: true };
    }

    completedNormally = true;
    return { accepted, rejected, stopped: false };
  } finally {
    if (!completedNormally) {
      await reader.cancel();
    }
    reader.releaseLock();
  }
}
